svg.script:
(function() {
  const svg = document.getElementById('venomHeaderSvg');
  const tentacles = document.getElementById('parallaxTentacles');
  const emblem = document.getElementById('parallaxEmblem');
  const body = document.getElementById('parallaxBody');
  const head = document.getElementById('interactiveHeadGroup');
  const eyes = document.getElementById('interactiveEyes');
  const lights = document.getElementById('parallaxLights');
  const topBrand = document.getElementById('topBrandSection');

  let targetX = 0, targetY = 0;
  let currentX = 0, currentY = 0;

  function onMove(clientX, clientY) {
    const rect = svg.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const normX = ((clientX - rect.left) / rect.width - 0.5) * 2;
    const normY = ((clientY - rect.top) / rect.height - 0.5) * 2;
    targetX = Math.max(-1, Math.min(1, normX));
    targetY = Math.max(-1, Math.min(1, normY));
  }

  window.addEventListener('mousemove', function(e) {
    onMove(e.clientX, e.clientY);
  }, { passive: true });

  window.addEventListener('touchmove', function(e) {
    if (e.touches && e.touches.length > 0) {
      onMove(e.touches[0].clientX, e.touches[0].clientY);
    }
  }, { passive: true });

  document.addEventListener('mouseleave', function() {
    targetX = 0;
    targetY = 0;
  });

  function animate() {
    currentX += (targetX - currentX) * 0.08;
    currentY += (targetY - currentY) * 0.08;

    tentacles.setAttribute('transform',
      `translate(${(-currentX * 26).toFixed(2)}, ${(-currentY * 16).toFixed(2)}) rotate(${(currentX * 1.4).toFixed(2)}, 720, 325)`
    );

    emblem.setAttribute('transform',
      `translate(${(-currentX * 14).toFixed(2)}, ${(-currentY * 10).toFixed(2)})`
    );

    body.setAttribute('transform',
      `translate(${(currentX * 10).toFixed(2)}, ${(currentY * 6).toFixed(2)})`
    );

    head.setAttribute('transform',
      `translate(${(currentX * 16).toFixed(2)}, ${(currentY * 12).toFixed(2)}) rotate(${(currentX * 5.5).toFixed(2)}, 720, 230)`
    );

    eyes.setAttribute('transform',
      `translate(${(currentX * 4.5).toFixed(2)}, ${(currentY * 3.5).toFixed(2)})`
    );

    lights.setAttribute('transform',
      `translate(${(currentX * 30).toFixed(2)}, ${(currentY * 20).toFixed(2)})`
    );

    topBrand.setAttribute('transform',
      `translate(${(currentX * 8).toFixed(2)}, ${(currentY * 5).toFixed(2)})`
    );

    requestAnimationFrame(animate);
  }

  requestAnimationFrame(animate);
})();
